<script lang="ts">
  import { AREAS, indexGuideline, loadGuideline, markReady, readHash, writeHash, type Guideline, type HashState, type Doc } from '../../shared/data.js';
  let g = $state.raw<Guideline | null>(null);
  let state = $state.raw<HashState>(readHash());
  let query = $state('');
  let outlineOpen = $state(innerWidth >= 700);
  let localKey = $state('');
  let error = $state('');
  const ix = $derived(g ? indexGuideline(g) : null);
  const question = $derived(state.view === 'trace' ? g?.questions.find(q => q.id === state.question) : null);
  const key = $derived(state.view === 'rule' ? `${state.document}:${state.sentence}` : state.view === 'trace' ? localKey || (question?.statements[0] ? `${question.statements[0].document}:${question.statements[0].sentence}` : '') : '');
  const doc = $derived(ix?.docs.get(key.slice(0, key.lastIndexOf(':'))));
  const sentence = $derived(ix?.sentence(key));
  const rule = $derived(ix?.rules.get(key));
  const concepts = $derived(g?.concepts.filter(c => c.mentions.includes(key)) ?? []);
  const citing = $derived(g?.questions.filter(q => q.statements.some(s => `${s.document}:${s.sentence}` === key)) ?? []);
  const siblings = $derived(doc?.rec == null ? [] : g?.documents.filter(d => d.rec === doc.rec && d.id !== doc.id).slice(0, 5) ?? []);
  const results = $derived(state.view === 'explore' ? g?.documents.flatMap(d => d.sentences.filter(s => `${s.ace} ${d.id}`.toLowerCase().includes(state.query.toLowerCase())).map(s => ({d,s}))) ?? [] : []);
  const notFound = $derived(state.view === 'trace' && !question || state.view === 'rule' && !sentence);
  function go(next: HashState) { localKey = ''; state = next; writeHash(next); }
  function select(d: string, n: number) { go({view:'rule',document:d,sentence:n}); }
  function docLabel(d: Doc) { return d.id.replace('cdc2022-opioid-', ''); }
  $effect(() => {
    const listener = () => { localKey = ''; state = readHash(); };
    addEventListener('hashchange', listener);
    loadGuideline().then(data => g = data).catch(e => error = String(e));
    return () => removeEventListener('hashchange', listener);
  });
  $effect(() => { if (g) { void state; queueMicrotask(markReady); } });
</script>

<svelte:head><title>Guideline workbench</title></svelte:head>
<header class="top"><div><strong>Guideline workbench</strong><span>CDC opioid prescribing guideline, 2022</span></div><form onsubmit={e => {e.preventDefault();go({view:'explore',query});}}><label for="search">Find in the knowledge base</label><div class="search"><input id="search" bind:value={query} placeholder="e.g. naloxone" /><button>Find</button></div></form></header>
{#if error}<p role="alert">{error}</p>{:else if !g || !ix}<p>Loading the guideline…</p>{:else}
<div class="workbench">
<aside><details class="outline" bind:open={outlineOpen}><summary>Guideline outline <small>{g.documents.length} documents</small></summary>
<nav aria-label="Guideline outline"><button class:current={state.view === 'overview'} onclick={() => go({view:'overview'})}>Guideline overview</button>
{#each AREAS as area}<details open><summary>{area.label}</summary>{#each area.recs as n}{@const rec = g.recommendations.find(r => r.number === n)!}<details open={doc?.rec === n}><summary>Recommendation {n} <small>{g.documents.filter(d => d.rec === n).length} docs</small></summary>{#each g.documents.filter(d => d.rec === n) as d}<details open={doc?.id === d.id}><summary>{docLabel(d)} <small>{d.kind}</small></summary>{#each d.sentences as s}<button class:current={key === `${d.id}:${s.n}`} onclick={() => select(d.id,s.n)} title={s.ace}>Sentence {s.n} <span>{s.ace}</span></button>{/each}</details>{/each}</details>{/each}</details>{/each}
<details><summary>Guideline-wide documents</summary>{#each g.documents.filter(d => d.rec === null) as d}<details><summary>{docLabel(d)}</summary>{#each d.sentences as s}<button onclick={() => select(d.id,s.n)}>Sentence {s.n}: {s.ace}</button>{/each}</details>{/each}</details>
</nav></details></aside>
<main><div class="crumb"><button onclick={() => go({view:'overview'})}>Guideline</button><span>/</span>{#if doc}<span>Recommendation {doc.rec ?? 'scope'}</span><span>/</span><span>{docLabel(doc)}</span>{:else}<span>{state.view}</span>{/if}</div>
<div class="tabs"><button class:active={state.view === 'overview'} onclick={() => go({view:'overview'})}>Shape of the guideline</button><details class="question-menu"><summary>Trace an answer</summary><div>{#each g.questions as q}<button onclick={() => go({view:'trace',question:q.id})}>{q.question}</button>{/each}</div></details></div>
<p class="notice">{g.derivation} The four clinical areas are the guideline PDF's own headings (BOX 3, page 13); the knowledge base holds no area record.</p><p class="notice">Outline nodes contain source records. Local graph edges show rules, mentions, sibling documents and answer citations.</p>
{#if notFound}<h1>Selection not found</h1><p>Choose a sentence from the guideline outline.</p>
{:else if state.view === 'overview'}
<h1>A whole guideline. One local view.</h1><p class="lede">Open an area, then a recommendation. Select a sentence to inspect its immediate connections.</p>
<div class="areas">{#each AREAS as area}<section><h2>{area.label}</h2><div class="rec-list">{#each area.recs as n}{@const r = g.recommendations.find(r => r.number === n)!}{@const d = ix.docs.get(r.id)!}<button class="rec" onclick={() => select(d.id,d.sentences.find(s => s.modal !== 'fact')?.n ?? d.sentences[0].n)}><strong>Recommendation {n}</strong><span>{r.source}</span><small>{r.implementation.length} implementation / {r.supporting.length} supporting documents</small></button>{/each}</div></section>{/each}</div>
{:else if state.view === 'explore'}
<h1>Find “{state.query}”</h1><p>{results.length} matching sentences. Select a result to open its local graph.</p><div class="results">{#each results as {d,s}}<button onclick={() => select(d.id,s.n)}><small>{docLabel(d)} / sentence {s.n} / page {d.page}</small><span>{s.ace}</span></button>{/each}{#if !results.length}<p>No matching sentence. Try another clinical term.</p>{/if}</div>
{:else}
{#if question}<h1>{question.question}</h1><p>Answer statements in source order. Select one to inspect its connections.</p><ol class="answer">{#each question.statements as s}<li><button class:chosen={key === `${s.document}:${s.sentence}`} onclick={() => localKey = `${s.document}:${s.sentence}`}><span>{ix.sentence(`${s.document}:${s.sentence}`)?.ace}</span><small>{s.document} / sentence {s.sentence} / page {ix.docs.get(s.document)?.page}</small></button></li>{/each}</ol>{:else}<h1>Sentence {sentence?.n}: local connections</h1>{/if}
{#if sentence && doc}
<p class="legend">Nodes are source records, rules, concepts or questions. Lines name their relation to the selected sentence.</p>
<div class="ego">
<svg class="wires" viewBox="0 0 1000 480" preserveAspectRatio="none" aria-hidden="true"><path d="M240 110 H345 V240 H420 M240 370 H345 V240 M580 240 H655 V110 H760 M655 240 V370 H760" /></svg>
<section class="neighbor rule"><h2>{rule ? 'Has clinical rule' : 'Has text reading'}</h2>{#if rule}<strong>{rule.mode}{rule.actions.some(a => a.polarity === 'negative') ? ' / negative action' : ''}</strong><p>{rule.condition ?? 'No condition in this rule record.'}</p><p>{rule.subject}: {rule.actions.map(a => `${a.polarity === 'negative' ? 'not ' : ''}${a.verb} ${a.object}`).join('; ')}</p>{:else}<p>Text reading, not the clinical parse.</p><p>{sentence.condition ?? 'No condition identified.'}</p><p>{sentence.conclusion}</p>{/if}</section>
<section class="focus"><small>Selected source sentence</small><p>{sentence.ace}</p><span>{docLabel(doc)} / sentence {sentence.n}</span><a href={`${g.pdf}#page=${doc.page}`} target="_blank" rel="noreferrer">Open guideline page {doc.page}</a></section>
<section class="neighbor concepts"><h2>Mentions {concepts.length} concepts</h2><div class="concept-list">{#each concepts as c}<button onclick={() => {query = c.label; go({view:'explore',query:c.label});}}>{c.label}</button>{/each}{#if !concepts.length}<p>No concept links in this record.</p>{/if}</div></section>
<section class="neighbor siblings"><h2>Shares recommendation with</h2>{#each siblings as d}<button onclick={() => select(d.id,d.sentences[0].n)}>{docLabel(d)} <small>{d.kind}</small></button>{/each}<small>Showing {siblings.length} of {g.documents.filter(d => d.rec === doc.rec && d.id !== doc.id).length} related documents.</small></section>
<section class="neighbor citing"><h2>Cited by {citing.length} {citing.length === 1 ? 'answer' : 'answers'}</h2>{#each citing as q}<button onclick={() => go({view:'trace',question:q.id})}>{q.question}</button>{/each}{#if !citing.length}<p>No catalog answer cites this sentence.</p>{/if}</section>
</div>
<details class="source" open><summary>Guideline source / page {doc.page}</summary><blockquote>{doc.source}</blockquote></details>
<details class="source"><summary>Connections as a list</summary><ul><li>Sentence is contained in {doc.id}, page {doc.page}.</li><li>{rule ? 'Clinical rule parses the selected sentence.' : 'Text reading heuristically splits the selected sentence.'}</li>{#each concepts as c}<li>Sentence mentions {c.label}.</li>{/each}{#each citing as q}<li>Answer cites sentence: {q.question}</li>{/each}{#each siblings as d}<li>Document shares recommendation: {d.id}.</li>{/each}</ul></details>
{/if}
{/if}
<div class="guards"><details><summary>Scope exclusions ({g.exclusions.length} records)</summary><p>The recommendations do not apply under these conditions. Absence of an exclusion does not establish that a patient belongs to the guideline population.</p>{#each g.exclusions as e}<p><button onclick={() => select(e.document,e.sentence)}>{e.document} / sentence {e.sentence}</button><br />{e.ace}</p>{/each}</details><details><summary>Superseded statements ({g.supersessions.length})</summary>{#each g.supersessions as s}<p><button onclick={() => select(s.document,s.sentence)}>{s.document} / sentence {s.sentence}</button><br /><s>{s.ace}</s><br />Superseded {String(s.date).replace(/(\d{4})(\d{2})(\d{2})/,'$1-$2-$3')} by <a href={s.url}>{s.citation}</a></p>{/each}</details></div>
<footer>CDC source material is free on the agency website. CDC does not endorse this prototype.</footer>
</main></div>{/if}

<style>
:global(button),:global(input),:global(summary),:global(a){outline-offset:4px} :global(:focus-visible){outline:3px solid var(--action)}
button{cursor:pointer;color:var(--text);background:transparent;border:0;text-align:left} a{color:var(--action)} small{font-size:12px;color:var(--text-muted)}
.top{display:flex;justify-content:space-between;gap:30px;padding:20px 30px;background:var(--surface-raised);border-bottom:1px solid var(--border)}.top strong{font-size:24px;display:block;line-height:1.2}.top span{font-size:13px;color:var(--text-muted)}form{width:300px}label{font-size:12px}.search{display:flex;border:1px solid var(--border)}input{width:100%;min-width:0;border:0;background:var(--surface);color:var(--text);padding:7px 10px}.search button{background:var(--action);color:var(--action-text);padding:6px 15px}
.workbench{display:grid;grid-template-columns:290px minmax(0,1fr)}aside{border-right:1px solid var(--border);background:var(--surface-sunken);height:calc(100vh - 94px);position:sticky;top:0;overflow:auto;padding:12px}summary{cursor:pointer}nav{font-size:13px}nav details{padding-left:12px;margin-top:8px}nav summary{padding:4px 0}nav button{display:block;width:100%;padding:7px 9px;font-size:12px;border-left:2px solid var(--border)}nav button span{display:block;max-height:36px;overflow:hidden;color:var(--text-muted)}.current{background:var(--surface-raised);border-left-color:var(--action)}.outline>summary{font-weight:700;margin-bottom:16px}.outline>summary small{display:block;font-weight:400}
main{min-width:0;padding:0 26px 30px}.crumb{display:flex;gap:9px;flex-wrap:wrap;padding:13px 0;font-size:12px;color:var(--text-muted)}.crumb button{color:var(--action);padding:0}.tabs{display:flex;align-items:start;gap:20px;border-bottom:1px solid var(--border);position:relative}.tabs>button,.question-menu>summary{padding:12px 0}.active{box-shadow:inset 0 -3px var(--action)}.question-menu>div{position:absolute;z-index:5;background:var(--surface-raised);border:1px solid var(--border);max-width:500px;padding:10px}.question-menu button{display:block;padding:8px}.notice{font-size:12px;color:var(--text-muted);max-width:85ch}h1{font-size:28px;line-height:1.2;margin:22px 0 12px;max-width:45ch}h2{font-size:15px;line-height:1.35;margin:0 0 13px}.lede{max-width:70ch;color:var(--text-muted)}.areas{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:24px 0}.areas section{border:1px solid var(--border);background:var(--surface-raised)}.areas h2{background:var(--surface-sunken);padding:13px;margin:0}.rec{display:block;width:100%;padding:13px;border-top:1px solid var(--border)}.rec strong{display:block;color:var(--action)}.rec span{display:block;font-size:13px;line-height:1.5;max-height:59px;overflow:hidden;margin:4px 0}.rec small{display:block}.rec:hover{background:var(--surface-sunken)}
.legend{font-size:12px;color:var(--text-muted)}.ego{position:relative;display:grid;grid-template-columns:1fr 1.15fr 1fr;grid-template-rows:auto auto;gap:26px 45px;min-height:400px;margin:25px 0}.wires{position:absolute;inset:0;width:100%;height:100%;z-index:0;pointer-events:none;fill:none;stroke:var(--border);stroke-width:1.5}.neighbor,.focus{z-index:1;background:var(--surface-raised);border:1px solid var(--border);padding:14px;min-width:0;font-size:13px}.neighbor p{overflow-wrap:anywhere;max-height:135px;overflow:auto}.focus{grid-column:2;grid-row:1/3;align-self:center;background:var(--action);color:var(--action-text);border:0;padding:20px}.focus p{font-size:19px;line-height:1.5;overflow-wrap:anywhere}.focus small,.focus a{color:inherit}.focus span,.focus a{display:block;font-size:12px;margin-top:10px}.rule{grid-column:1;grid-row:1}.concepts{grid-column:3;grid-row:1}.siblings{grid-column:1;grid-row:2}.citing{grid-column:3;grid-row:2}.neighbor button{display:block;width:100%;padding:4px 0;color:var(--action);font-size:13px;overflow-wrap:anywhere}.concept-list{max-height:180px;overflow:auto}.concept-list button{display:inline-block;width:auto;border:1px solid var(--border);margin:3px;padding:3px 6px}.source{border-top:1px solid var(--border);padding:15px 0}blockquote{font-family:var(--font-prose);font-size:15px;line-height:1.8;max-width:76ch;margin:15px 0}.guards{margin-top:25px;background:var(--surface-sunken);padding:15px}.guards details+details{margin-top:15px}.guards p{max-width:76ch;font-size:13px}.guards button{color:var(--action);padding:0}.answer{padding-left:24px;max-height:230px;overflow:auto;border-bottom:1px solid var(--border)}.answer button{display:block;padding:9px;border-left:3px solid var(--border);margin:8px 0}.answer small{display:block}.answer .chosen{border-color:var(--action);background:var(--surface-sunken)}.results button{display:block;width:100%;border-top:1px solid var(--border);padding:15px 0}.results small,.results span{display:block;max-width:76ch}.results span{margin-top:5px}footer{font-size:11px;color:var(--text-muted);margin-top:25px}
@media(max-width:1000px){.ego{gap:22px 18px;grid-template-columns:1fr 1fr}.focus{grid-column:1/3;grid-row:1}.rule{grid-column:1;grid-row:2}.concepts{grid-column:2;grid-row:2}.siblings{grid-column:1;grid-row:3}.citing{grid-column:2;grid-row:3}.wires{display:none}.areas{grid-template-columns:1fr}}
@media(max-width:700px){.top{display:block;padding:18px}.top strong{font-size:23px}form{width:100%;margin-top:16px}.workbench{display:block}aside{position:static;height:auto;max-height:210px;border-right:0;border-bottom:1px solid var(--border);padding:10px 16px}main{padding:0 16px 25px}.outline>summary{margin-bottom:7px}.outline>summary small{display:inline;font-weight:400}h1{font-size:25px}.tabs{gap:16px;font-size:13px}.ego{display:flex;flex-direction:column;gap:12px}.focus{order:-1}.focus p{font-size:19px}.neighbor p{max-height:none}.areas{gap:14px}blockquote{font-size:14px}.crumb{font-size:11px}.answer{padding-left:18px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style>
